widget.solution:
class MinStack:
    def __init__(self):
        self.items = []
        self.mins = []  # mins[-1] is the minimum of items

    def push(self, x):
        self.items.append(x)
        self.mins.append(x if not self.mins else min(x, self.mins[-1]))

    def pop(self):
        self.mins.pop()
        return self.items.pop()

    def top(self):
        return self.items[-1]

    def get_min(self):
        return self.mins[-1]

def stock_span(prices):
    spans = []
    stack = []  # indices of days with a higher close, nearest on top
    for i, p in enumerate(prices):
        while stack and prices[stack[-1]] <= p:
            stack.pop()
        spans.append(i + 1 if not stack else i - stack[-1])
        stack.append(i)
    return spans

