widget.solution:
class _Node:
    def __init__(self, key=None, val=None):
        self.key, self.val = key, val
        self.prev = self.next = None


class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.map = {}
        self.head, self.tail = _Node(), _Node()  # sentinels: most recent after head
        self.head.next, self.tail.prev = self.tail, self.head

    def _unlink(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _push_front(self, node):
        node.prev, node.next = self.head, self.head.next
        self.head.next.prev = node
        self.head.next = node

    def get(self, key):
        if key not in self.map:
            return -1
        node = self.map[key]
        self._unlink(node)
        self._push_front(node)
        return node.val

    def put(self, key, value):
        if key in self.map:
            node = self.map[key]
            node.val = value
            self._unlink(node)
        else:
            if len(self.map) == self.cap:
                old = self.tail.prev
                self._unlink(old)
                del self.map[old.key]
            node = _Node(key, value)
            self.map[key] = node
        self._push_front(node)

widget.prelude:
class Node:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def from_list(values):
    head = None
    for v in reversed(values):
        head = Node(v, head)
    return head

def to_list(head, limit=10000):
    out = []
    while head and len(out) < limit:
        out.append(head.val)
        head = head.next
    return out

def make_cycle(values, pos):
    """Build a list from values, then point the tail back at index pos (-1: no cycle)."""
    head = from_list(values)
    if head is None or pos < 0:
        return head
    cur, target, i = head, None, 0
    while True:
        if i == pos:
            target = cur
        if cur.next is None:
            break
        cur, i = cur.next, i + 1
    cur.next = target
    return head

import tracemalloc as _tm
def peak_bytes(f):
    _tm.start()
    try:
        f()
        return _tm.get_traced_memory()[1]
    finally:
        _tm.stop()

